from numpy.linalg import lstsq
t,x,v,a=df['t'].values,df['x'].values,df['v'].values,df['dv_dt'].values
SST=np.sum((a-a.mean())**2)
def lin(p):
    c,w,b,w2=p
    A=np.column_stack([x**1.5,(x/(1+c*x))*v,np.cos(w*t)*np.cos(b*x),np.sin(w2*t),np.ones_like(x)])
    coef=lstsq(A,a,rcond=None)[0]; return A@coef-a,coef
